{
  "permissions": {
    "deny": [
      "Bash(curl *|*sh)",
      "Bash(curl *|*bash)",
      "Bash(wget *|*sh)",
      "Bash(wget *|*bash)",
      "Bash(sudo *)",
      "Bash(chmod 777 *)",
      "Bash(chmod -R 777 *)",
      "Bash(osascript *)",
      "Bash(crontab -e*)",
      "Bash(crontab -r*)",
      "Bash(mkfs *)",
      "Bash(dd if=*)",
      "Bash(npm publish*)",
      "Bash(yarn publish*)",
      "Bash(pnpm publish*)",
      "Write(~/.ssh/*)",
      "Write(~/.zshrc)",
      "Write(~/.bashrc)",
      "Write(~/.profile)"
    ]
  },
  "hooks": {
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py --mode=stop; fi",
            "timeout": 30
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write|Bash|Task|NotebookEdit|TeamCreate|SendMessage|TaskCreate|TaskUpdate",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py --mode=post-tool; fi",
            "timeout": 15
          }
        ]
      },
      {
        "matcher": "Bash|Read",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/output_secret_filter.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/output_secret_filter.py; fi",
            "timeout": 15
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/security_sensitive_file_guard.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/security_sensitive_file_guard.py; fi",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Write|Edit",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/validate_state_yaml.py",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Write",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/monitor_translation_output.py",
            "timeout": 8
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py --mode=pre-compact; fi",
            "timeout": 30
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "matcher": "clear|compact|resume",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/context_guard.py --mode=restore; fi",
            "timeout": 15
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/block_destructive_commands.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/block_destructive_commands.py; fi",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/block_test_file_edit.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/block_test_file_edit.py; fi",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "if test -f \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/predictive_debug_guard.py; then python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/predictive_debug_guard.py; fi",
            "timeout": 10
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "matcher": "clear",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/save_context.py --trigger sessionend"
          }
        ]
      }
    ],
    "Setup": [
      {
        "matcher": "init",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/setup_init.py",
            "timeout": 30
          }
        ]
      },
      {
        "matcher": "maintenance",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"$CLAUDE_PROJECT_DIR\"/.claude/hooks/scripts/setup_maintenance.py",
            "timeout": 30
          }
        ]
      }
    ]
  }
}

